style.css:
/* Moonlit Lanterns — Roblox */

:root {
  /* swap these colors if you want */
  --my-night: #10172d;
  --my-blue: #192746;
  --my-gold: #ffc66b;
  --my-glow: #ffe1a0;
  --my-lavender: #aaa9e8;
  --my-text: #f8eddb;
}

/* midnight fantasy background */
html,
body {
  background: linear-gradient(
    135deg,
    var(--my-night),
    var(--my-blue),
    #24233f
  ) !important;
  color: var(--my-text) !important;
  font-family: Georgia, "Trebuchet MS", sans-serif !important;
}

/* golden links */
a {
  color: var(--my-gold) !important;
  transition: color 0.2s ease, text-shadow 0.2s ease !important;
}

a:hover {
  color: var(--my-glow) !important;
  text-shadow: 0 0 10px var(--my-gold) !important;
}

/* magical buttons */
button,
[role="button"] {
  border-radius: 12px !important;
  transition: 0.2s ease !important;
}

button:hover,
[role="button"]:hover {
  box-shadow: 0 0 14px #ffc66b66 !important;
}

/* soft golden borders on inputs */
input,
textarea {
  background: #17223a !important;
  color: var(--my-text) !important;
  border: 1px solid #b99560 !important;
  border-radius: 10px !important;
}

/* dreamy image corners */
img {
  border-radius: 10px;
}

/* elegant selection */
::selection {
  background: var(--my-gold) !important;
  color: var(--my-night) !important;
}
